    (n, p) = X.shape
    bits = 1 << np.arange(p, dtype=np.int64)
    full = (1 << p) - 1
    ld = np.longdouble
    (A, h) = (X.astype(ld), y.astype(ld))
    (abs_A, abs_h) = (np.abs(A), np.abs(h))
    (l0, l2, box) = map(ld, (lam0, lam2, M))
    dot_guard = ld(8 * (max(n, p) + 2)) * np.finfo(ld).eps
    sum_guard = ld(8 * (p + 4)) * np.finfo(ld).eps

    def down(x: np.longdouble) -> float:
        return float(np.nextafter(float(x), -np.inf))

    def primal(b: np.ndarray) -> float:
        b = np.asarray(b, dtype=ld)
        r = h - A @ b
        rmax = np.abs(r) + dot_guard * (abs_h + abs_A @ np.abs(b))
        f = (rmax @ rmax + l2 * (b @ b)) / 2 + l0 * np.count_nonzero(b)
        return float(np.nextafter(float(f * (1 + dot_guard + sum_guard)), np.inf))
    best = np.zeros(p)
    upper = primal(best)
    cache = {}

    def offer(b: np.ndarray) -> None:
        nonlocal best, upper
        value = primal(b)
        if value < upper:
