                b[idx] = np.clip(w, -M, M)
            offer(b)
            cache[mask] = b
        return cache[mask]
    d = None
    if p and M:
        gram = A.T @ A
        err = dot_guard * (abs_A.T @ abs_A)
        off = np.abs(gram) + err
        np.fill_diagonal(off, 0)
        diagonal = gram.diagonal() - err.diagonal()
        candidate = diagonal - (1 + sum_guard) * off.sum(axis=1) - sum_guard * np.abs(diagonal)
        if np.all(candidate >= 0) and np.any(candidate > 0):
