        raise ValueError('history propagation is not finite in float64')
    return q


@track_wormhole_skill("autogenous_prim_exponential_memory")
def exponential_hold_response(state: np.ndarray, forcing: np.ndarray, times: np.ndarray, tau: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
    """For finite state (N,B) and forcing (N,), increasing nonnegative times (M,), and positive tau (B,), return branch increments (N,M,B) and time-zero rates (N,B)."""
    q, u, t, tau = _hold_inputs(state, forcing, times, tau)
    with np.errstate(over='ignore', under='ignore', invalid='ignore'):
        gap = u[:, None] - q
        gain = -np.expm1(-t[:, None] / tau)
        increments = gap[:, None, :] * gain
        initial_rate = gap / tau
    if not np.isfinite(increments).all() or not np.isfinite(initial_rate).all():
        raise ValueError('hold response is not finite in float64')
    return (increments, initial_rate)


@track_wormhole_skill("autogenous_prim_exponential_memory")
def verify_exponential_hold(state: np.ndarray, forcing: np.ndarray, times: np.ndarray, tau: np.ndarray, increments: np.ndarray, initial_rate: np.ndarray, *, rtol: float=1e-09, atol: float=1e-12) -> bool:
    """For finite state (N,B), forcing (N,), increments (N,M,B), and initial rate (N,B) on increasing nonnegative times (M,) with positive tau (B,) and finite nonnegative tolerances, return whether the hold operator and time-zero derivative match."""
    q, u, t, tau = _hold_inputs(state, forcing, times, tau)
    y = _real(increments, 'increments')
    rate = _real(initial_rate, 'initial_rate')
    if y.shape != (u.size, t.size, tau.size) or rate.shape != q.shape:
        raise ValueError('expected increments (N,M,B) and initial_rate (N,B)')
    if not (math.isfinite(rtol) and math.isfinite(atol) and (rtol >= 0) and (atol >= 0)):
        raise ValueError('tolerances must be finite and nonnegative')
    previous = np.concatenate((np.zeros_like(y[:, :1, :]), y[:, :-1, :]), axis=1)
    with np.errstate(over='ignore', under='ignore', invalid='ignore'):
        gap = u[:, None] - q
        z = -np.diff(t, prepend=0.0)[:, None] / tau
        expected = np.exp(z) * previous - np.expm1(z) * gap[:, None, :]
        expected_rate = gap / tau
    if not np.isfinite(expected).all() or not np.isfinite(expected_rate).all():
        raise ValueError('hold operator is not finite in float64')
    return bool(np.allclose(y, expected, rtol=rtol, atol=atol) and np.allclose(rate, expected_rate, rtol=rtol, atol=atol))

"""Autogenously Sublated Scientific Wormhole Module `autogenous_sparse_ridge_certification` (Container Unit-Tested, Zero Path Leakage)."""
from __future__ import annotations
import math
import numpy as np
import numpy as np
from scipy.optimize import lsq_linear, minimize
from . import track_wormhole_skill


@track_wormhole_skill("autogenous_sparse_ridge_certification")
def solve_and_certify_l0(X: np.ndarray, y: np.ndarray, lam0: float, lam2: float, M: float, eps: float=1e-06, *, max_leaves: int=90) -> dict:
    """Certify boxed sparse ridge regression with at most 16 real predictors.

    The objective is ||y-Xb||^2/2 + lam0*||b||_0 + lam2*||b||^2/2.
    Supply both nonnegative penalties and the nonnegative box radius M;
    neither penalty is chosen automatically. The default absolute gap is
    1e-6. Leaves partition binary indicator space: an active indicator pays
    lam0 but permits a zero coefficient. Minimizing over indicators then
    recovers the L0 objective, including ties and rank-deficient designs.

    The returned upper bound is the feasible objective rounded conservatively
    upward. The numerical guards assume finite arithmetic at the input scale;
    if the requested gap cannot be established, raise ArithmeticError. A
    leaf-budget overflow can require up to 2**p box-ridge fits.
    """
    (X, y) = (np.asarray(X, dtype=float), np.asarray(y, dtype=float))
    (lam0, lam2, M, eps) = map(float, (lam0, lam2, M, eps))
    if X.ndim != 2 or X.shape[0] < 1 or X.shape[1] > 16 or (y.shape != (X.shape[0],)):
        raise ValueError('expected X with shape (n, p), n >= 1, p <= 16, and y with shape (n,)')
    if not (np.isfinite(X).all() and np.isfinite(y).all() and np.isfinite([lam0, lam2, M, eps]).all()):
        raise ValueError('inputs must be finite')
    if min(lam0, lam2, M) < 0 or eps <= 0 or (not isinstance(max_leaves, (int, np.integer))) or (max_leaves < 1):
        raise ValueError('expected nonnegative penalties and box, positive eps, and a positive integer leaf budget')
    (n, p) = X.shape
    bits = 1 << np.arange(p, dtype=np.int64)
    full = (1 << p) - 1
    ld = np.longdouble
    (A, h) = (X.astype(ld), y.astype(ld))
    (abs_A, abs_h) = (np.abs(A), np.abs(h))
    (l0, l2, box) = map(ld, (lam0, lam2, M))
    dot_guard = ld(8 * (max(n, p) + 2)) * np.finfo(ld).eps
    sum_guard = ld(8 * (p + 4)) * np.finfo(ld).eps

    def down(x: np.longdouble) -> float:
        return float(np.nextafter(float(x), -np.inf))

    def primal(b: np.ndarray) -> float:
        b = np.asarray(b, dtype=ld)
        r = h - A @ b
        rmax = np.abs(r) + dot_guard * (abs_h + abs_A @ np.abs(b))
        f = (rmax @ rmax + l2 * (b @ b)) / 2 + l0 * np.count_nonzero(b)
        return float(np.nextafter(float(f * (1 + dot_guard + sum_guard)), np.inf))
    best = np.zeros(p)
    upper = primal(best)
    cache = {}

    def offer(b: np.ndarray) -> None:
        nonlocal best, upper
        value = primal(b)
        if value < upper:
            (best, upper) = (b.copy(), value)

    def fit(mask: int) -> np.ndarray:
        if mask not in cache:
            idx = np.flatnonzero(mask & bits)
            b = np.zeros(p)
            if idx.size and M:
                (design, rhs) = (X[:, idx], y)
                if lam2:
                    design = np.vstack((design, np.sqrt(lam2) * np.eye(idx.size)))
                    rhs = np.r_[rhs, np.zeros(idx.size)]
                w = np.linalg.lstsq(design, rhs, rcond=None)[0]
                if np.any(np.abs(w) > M):
                    w = lsq_linear(design, rhs, bounds=(-M, M), method='bvls', tol=1e-14).x
                b[idx] = np.clip(w, -M, M)
            offer(b)
            cache[mask] = b
        return cache[mask]
    d = None
    if p and M:
        gram = A.T @ A
        err = dot_guard * (abs_A.T @ abs_A)
        off = np.abs(gram) + err
        np.fill_diagonal(off, 0)
        diagonal = gram.diagonal() - err.diagonal()
        candidate = diagonal - (1 + sum_guard) * off.sum(axis=1) - sum_guard * np.abs(diagonal)
        if np.all(candidate >= 0) and np.any(candidate > 0):
            d = candidate

    def terms(z: np.ndarray, curv: float | np.ndarray, zero: int, active: int) -> np.longdouble:
        if M:
            b = np.minimum(np.divide(z, curv, out=np.full(p, box), where=curv > 0), box)
            gain = b * (z - curv * b / 2)
        else:
            gain = np.zeros(p, dtype=ld)
        fixed = active & bits != 0
        free = (zero | active) & bits == 0
        v = l0 - gain
        return v[fixed].sum() + np.minimum(0, v[free]).sum() - sum_guard * (p * l0 + gain[fixed | free].sum())

    def residual_dual(u: np.ndarray, zero: int, active: int) -> float:
        u = np.asarray(u, dtype=ld)
        a = np.abs(u)
        z = np.abs(A.T @ u) + dot_guard * (abs_A.T @ a)
        q = u @ u / 2
        return down(h @ u - q + terms(z, l2, zero, active) - (dot_guard + sum_guard) * (abs_h @ a + q))

    def witness(b: np.ndarray, zero: int, active: int) -> float:
        b = np.asarray(b, dtype=ld)
        r = h - A @ b
        lb = residual_dual(r, zero, active)
        if d is not None:
            re = dot_guard * (abs_h + abs_A @ np.abs(b))
            db = d * b
            z = np.abs(A.T @ r + db) + (1 + dot_guard) * (abs_A.T @ re) + (dot_guard + sum_guard) * (abs_A.T @ np.abs(r) + np.abs(db))
            (q, center) = (r @ r / 2, db @ b / 2)
            v = h @ r - q + center + terms(z, d + l2, zero, active)
            v -= (dot_guard + sum_guard) * (abs_h @ np.abs(r) + q + center)
            v -= (1 + dot_guard) * ((abs_h + np.abs(r) + re / 2) @ re)
            lb = max(lb, down(v))
        return lb

    def target() -> np.longdouble:
        return ld(upper) - ld(eps)

    def result(partition: dict) -> dict:
        if not np.isfinite(upper) or any((not np.isfinite(lb) or lb < target() for (lb, _) in partition.values())):
            raise ArithmeticError('could not certify the requested absolute gap')
        return {'beta': best, 'upper_bound': upper, 'tree_leaves': [{'fixed_zero': np.flatnonzero(zero & bits).tolist(), 'fixed_active': np.flatnonzero(active & bits).tolist(), 'lower_bound': lb} for ((zero, active), (lb, _)) in sorted(partition.items())]}
    if not p or not M:
        return result({(0, 0): (residual_dual(h, 0, 0), best)})
    if not lam0:
        b = fit(full)
        lb = witness(b, 0, 0)
        if lb >= target():
            return result({(0, 0): (lb, b)})
    present = X != 0
    (remaining, used) = (np.ones(p, dtype=bool), np.zeros(n, dtype=bool))
    blocks = []
    while remaining.any():
        cols = np.zeros(p, dtype=bool)
        cols[np.flatnonzero(remaining)[0]] = True
        while True:
            rows = present[:, cols].any(axis=1)
            expanded = cols | present[rows].any(axis=0)
            if np.array_equal(expanded, cols):
                break
            cols = expanded
        blocks.append((np.flatnonzero(cols), rows))
        remaining[cols] = False
        used |= rows
    if len(blocks) > 1 and max((idx.size for (idx, _) in blocks)) <= 8:
        combined = np.zeros(p)
        lower = [residual_dual(np.where(used, 0, h), full, 0)]
        for (idx, rows) in blocks:
            (local_A, local_h) = (A[rows][:, idx], h[rows])
            (local_lb, local_best) = (np.inf, np.inf)
            for subset in range(1 << idx.size):
                mask = sum((int(bits[j]) for (k, j) in enumerate(idx) if subset & 1 << k))
                b = fit(mask)[idx].astype(ld)
                r = local_h - local_A @ b
                f = (r @ r + l2 * (b @ b)) / 2 + l0 * np.count_nonzero(b)
                if f < local_best:
                    (local_best, combined[idx]) = (f, b)
                u = np.zeros(n, dtype=ld)
                u[rows] = r
                local_lb = min(local_lb, residual_dual(u, full ^ mask, mask))
            lower.append(local_lb)
        offer(combined)
        a = np.asarray(lower, dtype=ld)
        lb = down(a.sum() - sum_guard * np.abs(a).sum())
        if lb >= target():
            return result({(0, 0): (lb, combined)})
    (G, c) = (X.T @ X, X.T @ y)
    t = (float(min(box, np.sqrt(2 * l0) / np.sqrt(l2))) if lam2 else M) if lam0 else 0.0
    slope = lam0 / t + lam2 * t / 2 if t else 0.0

    def relax(zero: int, active: int, start: np.ndarray, threshold: float) -> tuple[float, np.ndarray]:
        free = np.flatnonzero((zero | active) & bits == 0)
        if not free.size:
            b = fit(active)
            return (witness(b, zero, active), b)
        lb = witness(start, zero, active)
        if lb >= threshold:
            return (lb, start)
        fixed = np.flatnonzero(active & bits != 0)
        (j, sign) = (fixed.tolist(), [1.0] * fixed.size)
        (lin, diag) = ([0.0] * fixed.size, [lam2] * fixed.size)
        (bounds, x0) = ([(-M, M)] * fixed.size, start[fixed].tolist())
        if not lam0:
            j.extend(free)
            sign.extend([1.0] * free.size)
            lin.extend([0.0] * free.size)
            diag.extend([lam2] * free.size)
            bounds.extend([(-M, M)] * free.size)
            x0.extend(start[free])
        else:
            for s in (1.0, -1.0):
                v = np.maximum(0.0, s * start[free])
                for (cap, cost, curvature, initial) in ((t, slope, 0.0, np.minimum(t, v)), (M - t, lam2 * t, lam2, np.maximum(0.0, v - t))):
                    if cap > 0:
                        j.extend(free)
                        sign.extend([s] * free.size)
                        lin.extend([cost] * free.size)
                        diag.extend([curvature] * free.size)
                        bounds.extend([(0.0, cap)] * free.size)
                        x0.extend(initial)
        j = np.asarray(j, dtype=int)
        sign = np.asarray(sign)
        H = G[np.ix_(j, j)] * sign[:, None] * sign
        H.flat[::len(j) + 1] += diag
        q = np.asarray(lin) - c[j] * sign

        def objective(v: np.ndarray) -> tuple[float, np.ndarray]:
            hv = H @ v
            return (float((0.5 * hv + q) @ v), hv + q)
        opt = minimize(objective, x0, jac=True, method='L-BFGS-B', bounds=bounds, options={'ftol': 2.3e-16, 'gtol': 2e-12, 'maxiter': 700, 'maxls': 40})
        b = np.clip(np.bincount(j, sign * opt.x, minlength=p), -M, M)
        trial = witness(b, zero, active)
        return (trial, b) if trial > lb else (lb, start)
    if d is not None:
        a = G.diagonal() + lam2
        z = np.abs(c)
        b = np.minimum(np.divide(z, a, out=np.full(p, M), where=a > 0), M)
        fit(int(bits[b * (z - a * b / 2) > lam0].sum()))
    (visited, children) = ({}, {})
    search_tol = min(0.05 * eps, 2e-10)

    def search(key: tuple[int, int], start: np.ndarray) -> None:
        (zero, active) = key
        (lb, b) = visited[key] = relax(zero, active, start, upper - search_tol)
        if lb >= upper - search_tol or zero | active == full:
            return
        free = np.flatnonzero((zero | active) & bits == 0)
        magnitude = np.abs(b[free])
        for frac in (0.5, 0.15, 0.85):
            chosen = free[(magnitude >= frac * t) & (magnitude > 0)]
            fit(active | int(bits[chosen].sum()))
